"use client";

import Link from "next/link";
import { useParams, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import { NotesPanel } from "@/components/NotesPanel";
import { StageBadge } from "@/components/StageBadge";
import { StatusBadge } from "@/components/StatusBadge";
import { createRecordNote, deleteRecordNote, getRecordById, getRecordNotes, patchRecord } from "@/services/api";
import { Candidate, CandidateStage, CandidateStatus, Note, STAGE_OPTIONS, STATUS_OPTIONS } from "@/types/candidate";

export default function CandidateDetailPage() {
  const params = useParams<{ id: string }>();
  const id = params.id;
  const searchParams = useSearchParams();
  const updated = searchParams.get("updated") === "1";

  const [candidate, setCandidate] = useState<Candidate | null>(null);
  const [notes, setNotes] = useState<Note[]>([]);
  const [loadingCandidate, setLoadingCandidate] = useState(true);
  const [loadingNotes, setLoadingNotes] = useState(true);
  const [statusPatchLoading, setStatusPatchLoading] = useState(false);
  const [stagePatchLoading, setStagePatchLoading] = useState(false);
  const [savingNote, setSavingNote] = useState(false);
  const [deletingNoteId, setDeletingNoteId] = useState<string | null>(null);
  const [candidateError, setCandidateError] = useState("");
  const [notesError, setNotesError] = useState("");
  const [notesSuccess, setNotesSuccess] = useState("");
  const [patchSuccess, setPatchSuccess] = useState("");

  useEffect(() => {
    async function loadCandidate() {
      setLoadingCandidate(true);
      setCandidateError("");

      try {
        const data = await getRecordById(id);
        setCandidate(data);
      } catch (error) {
        setCandidateError(error instanceof Error ? error.message : "No se pudo cargar el detalle.");
      } finally {
        setLoadingCandidate(false);
      }
    }

    async function loadNotes() {
      setLoadingNotes(true);
      setNotesError("");

      try {
        const data = await getRecordNotes(id);
        setNotes(data);
      } catch (error) {
        setNotesError(error instanceof Error ? error.message : "No se pudieron cargar las notas.");
      } finally {
        setLoadingNotes(false);
      }
    }

    void loadCandidate();
    void loadNotes();
  }, [id]);

  async function handleStatusChange(nextStatus: CandidateStatus) {
    if (!candidate || candidate.status === nextStatus) {
      return;
    }

    setPatchSuccess("");
    setCandidateError("");
    setStatusPatchLoading(true);

    try {
      const updated = await patchRecord(candidate.id, { status: nextStatus });
      setCandidate(updated);
      setPatchSuccess("Estado actualizado correctamente.");
    } catch (error) {
      setCandidateError(error instanceof Error ? error.message : "No se pudo actualizar el estado.");
    } finally {
      setStatusPatchLoading(false);
    }
  }

  async function handleStageChange(nextStage: CandidateStage) {
    if (!candidate || candidate.stage === nextStage) {
      return;
    }

    setPatchSuccess("");
    setCandidateError("");
    setStagePatchLoading(true);

    try {
      const updated = await patchRecord(candidate.id, { stage: nextStage });
      setCandidate(updated);
      setPatchSuccess("Etapa actualizada correctamente.");
    } catch (error) {
      setCandidateError(error instanceof Error ? error.message : "No se pudo actualizar la etapa.");
    } finally {
      setStagePatchLoading(false);
    }
  }

  async function handleCreateNote(content: string): Promise<boolean> {
    if (!candidate) {
      return false;
    }

    setSavingNote(true);
    setNotesError("");
    setNotesSuccess("");

    try {
      const newNote = await createRecordNote(candidate.id, { content });
      setNotes((prev) => [newNote, ...prev]);
      setCandidate((prev) => (prev ? { ...prev, notes_count: prev.notes_count + 1 } : prev));
      setNotesSuccess("Nota agregada correctamente.");
      return true;
    } catch (error) {
      setNotesError(error instanceof Error ? error.message : "No se pudo crear la nota.");
      return false;
    } finally {
      setSavingNote(false);
    }
  }

  async function handleDeleteNote(noteId: string): Promise<boolean> {
    if (!candidate) {
      return false;
    }

    setDeletingNoteId(noteId);
    setNotesError("");
    setNotesSuccess("");

    try {
      await deleteRecordNote(candidate.id, noteId);
      setNotes((prev) => prev.filter((note) => note.id !== noteId));
      setCandidate((prev) =>
        prev
          ? {
              ...prev,
              notes_count: Math.max(0, prev.notes_count - 1),
            }
          : prev,
      );
      setNotesSuccess("Nota eliminada correctamente.");
      return true;
    } catch (error) {
      setNotesError(error instanceof Error ? error.message : "No se pudo eliminar la nota.");
      return false;
    } finally {
      setDeletingNoteId(null);
    }
  }

  return (
    <main className="mx-auto w-full max-w-6xl px-4 py-8 sm:px-6 lg:px-8">
      {updated ? (
        <p className="mb-4 rounded-lg bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700">
          Candidatura actualizada correctamente.
        </p>
      ) : null}

      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <Link href="/" className="text-sm font-semibold text-cyan-700 hover:text-cyan-600">
          Volver al listado
        </Link>
        {candidate ? (
          <Link
            href={`/candidates/${candidate.id}/edit`}
            className="rounded-lg border border-slate-300 px-3 py-1.5 text-sm font-semibold text-slate-700 hover:border-cyan-400 hover:text-cyan-700"
          >
            Editar candidatura
          </Link>
        ) : null}
      </div>

      {loadingCandidate ? <p className="text-sm text-slate-600">Cargando detalle...</p> : null}
      {candidateError ? <p className="rounded-lg bg-rose-50 px-3 py-2 text-sm text-rose-700">{candidateError}</p> : null}

      {candidate ? (
        <>
          <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
              <div>
                <h1 className="text-2xl font-bold text-slate-900">{candidate.full_name}</h1>
                <p className="mt-1 text-sm text-slate-600">{candidate.position}</p>
                <p className="mt-1 text-sm text-slate-500">Aplicó el {new Date(candidate.applied_at).toLocaleDateString("es-ES")}</p>
              </div>
              <div className="flex gap-2">
                <StatusBadge status={candidate.status} />
                <StageBadge stage={candidate.stage} />
              </div>
            </div>

            <div className="mt-6 grid gap-6 md:grid-cols-2">
              <div className="space-y-1 text-sm text-slate-700">
                <p>
                  <span className="font-semibold">Email:</span> {candidate.email}
                </p>
                <p>
                  <span className="font-semibold">Teléfono:</span> {candidate.phone}
                </p>
                <p>
                  <span className="font-semibold">Experiencia:</span> {candidate.experience_years} años
                </p>
                <p>
                  <span className="font-semibold">LinkedIn:</span>{" "}
                  {candidate.linkedin_url ? (
                    <a href={candidate.linkedin_url} target="_blank" rel="noreferrer" className="text-cyan-700 hover:text-cyan-600">
                      Ver perfil
                    </a>
                  ) : (
                    "No disponible"
                  )}
                </p>
                <p>
                  <span className="font-semibold">CV:</span>{" "}
                  {candidate.cv_url ? (
                    <a href={candidate.cv_url} target="_blank" rel="noreferrer" className="text-cyan-700 hover:text-cyan-600">
                      Abrir CV
                    </a>
                  ) : (
                    "No disponible"
                  )}
                </p>
              </div>

              <div className="space-y-4">
                <div>
                  <label htmlFor="statusControl" className="mb-1 block text-sm font-medium text-slate-700">
                    Estado del proceso
                  </label>
                  <select
                    id="statusControl"
                    value={candidate.status}
                    onChange={(event) => handleStatusChange(event.target.value as CandidateStatus)}
                    disabled={statusPatchLoading}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    {STATUS_OPTIONS.map((status) => (
                      <option key={status.value} value={status.value}>
                        {status.label}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label htmlFor="stageControl" className="mb-1 block text-sm font-medium text-slate-700">
                    Etapa del proceso
                  </label>
                  <select
                    id="stageControl"
                    value={candidate.stage}
                    onChange={(event) => handleStageChange(event.target.value as CandidateStage)}
                    disabled={stagePatchLoading}
                    className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-900 focus:border-cyan-500 focus:outline-none disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    {STAGE_OPTIONS.map((stage) => (
                      <option key={stage.value} value={stage.value}>
                        {stage.label}
                      </option>
                    ))}
                  </select>
                </div>

                {patchSuccess ? <p className="rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700">{patchSuccess}</p> : null}
              </div>
            </div>
          </section>

          <div className="mt-6">
            <NotesPanel
              notes={notes}
              loading={loadingNotes}
              saving={savingNote}
              deletingNoteId={deletingNoteId}
              onCreate={handleCreateNote}
              onDelete={handleDeleteNote}
              error={notesError}
              success={notesSuccess}
            />
          </div>
        </>
      ) : null}
    </main>
  );
}
